-- FORGE / Gym App — run in Supabase SQL Editor
create extension if not exists pgcrypto;
create table if not exists public.profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text,avatar_url text,created_at timestamptz not null default now());
-- Shared catalog: all signed-in users can read; only administrators manage entries.
create table if not exists public.exercises(id uuid primary key default gen_random_uuid(),name text not null unique,muscle_group text not null,equipment text,instructions text,is_active boolean not null default true,created_at timestamptz not null default now());
create table if not exists public.workouts(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,name text not null default 'Entrenamiento',performed_at timestamptz not null default now(),duration_minutes integer check(duration_minutes is null or duration_minutes>=0),notes text,created_at timestamptz not null default now());
create table if not exists public.workout_sets(id uuid primary key default gen_random_uuid(),workout_id uuid not null references public.workouts(id) on delete cascade,exercise_id uuid not null references public.exercises(id),set_number integer not null check(set_number>0),reps integer not null check(reps>0),weight_kg numeric(7,2) not null default 0 check(weight_kg>=0),rest_seconds integer check(rest_seconds is null or rest_seconds>=0),rpe numeric(3,1) check(rpe is null or(rpe>=0 and rpe<=10)),notes text,created_at timestamptz not null default now(),unique(workout_id,exercise_id,set_number));
create index if not exists workouts_user_date_idx on public.workouts(user_id,performed_at desc);
create index if not exists workout_sets_workout_idx on public.workout_sets(workout_id);
create index if not exists workout_sets_exercise_idx on public.workout_sets(exercise_id);
alter table public.profiles enable row level security;alter table public.exercises enable row level security;alter table public.workouts enable row level security;alter table public.workout_sets enable row level security;
drop policy if exists "profile read own" on public.profiles;create policy "profile read own" on public.profiles for select to authenticated using(auth.uid()=id);
drop policy if exists "profile update own" on public.profiles;create policy "profile update own" on public.profiles for update to authenticated using(auth.uid()=id) with check(auth.uid()=id);
drop policy if exists "profile insert own" on public.profiles;create policy "profile insert own" on public.profiles for insert to authenticated with check(auth.uid()=id);
drop policy if exists "authenticated read active exercises" on public.exercises;create policy "authenticated read active exercises" on public.exercises for select to authenticated using(is_active=true);
drop policy if exists "own workouts only" on public.workouts;create policy "own workouts only" on public.workouts for all to authenticated using(auth.uid()=user_id) with check(auth.uid()=user_id);
drop policy if exists "own workout sets only" on public.workout_sets;create policy "own workout sets only" on public.workout_sets for all to authenticated using(exists(select 1 from public.workouts w where w.id=workout_id and w.user_id=auth.uid())) with check(exists(select 1 from public.workouts w where w.id=workout_id and w.user_id=auth.uid()));
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$ begin insert into public.profiles(id,display_name,avatar_url) values(new.id,coalesce(new.raw_user_meta_data->>'full_name',new.raw_user_meta_data->>'name'),new.raw_user_meta_data->>'avatar_url') on conflict(id) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
